// Thermo.ts — plain getter vs computed(), side by side.
import { computed, ref } from 'vue';
import { Reactive } from '../../ivue';

class $Thermo {
  // Run counters are plain fields: incrementing them inside getter bodies is
  // side-effect-free for the graph (a plain-field write triggers nothing).
  fahrenheitRuns = 0;
  statusRuns = 0;

  get celsius() {
    return ref(21);
  }

  // Plain getter: re-derives on EVERY render — even unrelated ones.
  get fahrenheit() {
    this.fahrenheitRuns++;
    return Math.round((this.celsius.value * 9) / 5 + 32);
  }

  // computed(): memoized — its body runs only when celsius actually changed.
  get status() {
    return computed(() => this.deriveStatus());
  }

  deriveStatus() {
    this.statusRuns++;
    const celsius = this.celsius.value;
    if (celsius < 10) return 'Cold';
    if (celsius < 18) return 'Cool';
    if (celsius < 26) return 'Comfortable';
    return 'Warm';
  }
}

export namespace Thermo {
  export const $Class = $Thermo; // raw — children `extends` this
  export const Class = Reactive($Class); // reactive — you `new` this
  export type Instance = typeof Class.Instance; // defineExpose type & reactive() interop
}

export const manifest = {
  slug: 'derived',
  title: 'Plain getter vs computed()',
  blurb: 'The same derivation both ways — watch whose body re-runs, and when.',
  docsPath: '/examples/derived',
} as const;

// Sensor.ts — $watch and $stopEffects on an instance you control by hand.
import { ref } from 'vue';
import { Reactive } from '../../ivue';

class $Sensor {
  get temp() {
    return ref(20);
  }
  get watching() {
    return ref(false);
  }
  get fired() {
    return ref(0);
  }
  get lastChange() {
    return ref('');
  }

  #stopWatch?: () => void;

  start() {
    if (this.watching.value) return;
    this.watching.value = true;
    // $watch registers in the instance's lazy effect scope
    this.#stopWatch = (this as any).$watch(
      () => this.temp.value,
      (newTemp: number, oldTemp: number) => this.onTempChanged(newTemp, oldTemp),
    );
  }

  stop() {
    this.#stopWatch?.();
    this.#stopWatch = undefined;
    this.watching.value = false;
  }

  dispose() {
    (this as any).$stopEffects(); // stops the scope, clears every cached cell
    this.watching.value = false; // fresh cells materialize on next access
  }

  onTempChanged(newTemp: number, oldTemp: number) {
    this.fired.value++;
    this.lastChange.value = `${oldTemp} → ${newTemp}`;
  }
}

export namespace Sensor {
  export const $Class = $Sensor; // raw — children `extends` this
  export const Class = Reactive($Class); // reactive — you `new` this
  export type Instance = typeof Class.Instance; // defineExpose type & reactive() interop
}

export const manifest = {
  slug: 'lifecycle',
  title: '$watch & $stopEffects',
  blurb: 'An instance-scoped watcher, started, stopped and disposed live.',
  docsPath: '/examples/lifecycle',
} as const;

