import fileUpload from 'express-fileupload';
import { reqContextService } from '../../services/requestContext.singleton';
import {
  type NextFunction,
  type RequestHandler,
  type Request,
  type Response
} from 'express';

/**
 * Legacy fallback media uploader for uploading files
 * through our server without serverless AWS S3.
 *
 * Creates req.files object with all
 * the files that will be uploaded.
 * @see ./media.routes.ts -> '/upload' route.
 * @see https://github.com/richardgirges/express-fileupload
 *
 * @param sizeLimit File Size Limit in Megabytes
 * @returns Express File Upload Middleware
 */
export function MediaUploader(
  sizeLimit = 5000, // 5GB default limit
  useTempFiles = true
): RequestHandler {
  const fileUploadMiddleware = fileUpload({
    limits: { fileSize: sizeLimit * 1024 * 1024 },
    parseNested: true,
    abortOnLimit: true,
    useTempFiles,
    responseOnLimit: JSON.stringify({
      name: 'file_size_limit_exceeded',
      statusCode: 413,
      message: `Only files under ${sizeLimit}MB are allowed.`,
      clientMessage: `Only files under ${sizeLimit}MB are allowed.`
    }),
    tempFileDir: './tmp/',
    debug: process.env.NODE_ENV === 'development'
  });

  return (req: Request, res: Response, next: NextFunction) => {
    const context = reqContextService.getRequestContext(); // Save context
    fileUploadMiddleware(req as any, res as any, (err?: any) => {
      if (err) {
        next(err);
        return;
      }
      reqContextService.setRequestContext(context); // Restore context
      next();
    });
  };
}

