302	/**
303	 * Authorize-then-redirect: instead of proxying S3 bytes through the API
304	 * worker (which pushes entire files through the event loop — the 2026-07-06
305	 * stall was ~5.7 GB of video in 12 minutes), issue a time-limited presigned
306	 * S3 URL and 302 the client to it. S3 serves the bytes directly — including
307	 * Range requests, so video seeking still works — and the worker never
308	 * carries them.
309	 */
310	export async function streamS3FileToResponse(
311	  _req: Request,
312	  res: Response,
313	  opts: StreamFileOptions
314	): Promise<void> {
315	  const s3 = AwsService.getS3Client();
316	  const params = { Bucket: opts.bucket, Key: opts.key };
317	
318	  // HEAD: 404 early on missing keys + pick up the metadata mimetype override
319	  // (signed-upload files land as binary/octet-stream; metadata carries the
320	  // real type, which S3 applies via the response-content-type override).
321	  let head;
322	  try {
323	    head = await s3.send(new HeadObjectCommand(params));
324	  } catch (e: any) {
325	    throw new MediaError(e);
326	  }
327	
328	  const contentType =
329	    head?.Metadata?.mimetype ?? head?.ContentType ?? 'application/octet-stream';
330	
331	  // Content-Disposition (same RFC 6266 encoding as the old proxy path, now
332	  // applied by S3 via the response-content-disposition override)
333	  const dispositionType = opts.download ? 'attachment' : 'inline';
334	  let dispositionHeader = dispositionType;
335	  if (opts.name) {
336	    const safeName = String(opts.name);
337	
338	    // 1. Create an ASCII-only fallback by replacing non-ASCII chars with underscores
339	    // Also escape any quotes to prevent header injection
340	    const asciiName = safeName
341	      .replace(/[^\x20-\x7E]/g, '_')
342	      .replaceAll('"', '\\"');
343	
344	    // 2. Properly encode the UTF-8 version for modern browsers
345	    const utf8Name = encodeURIComponent(safeName);
346	
347	    // 3. Append both to the header per RFC 6266
348	    dispositionHeader += `; filename="${asciiName}"; filename*=UTF-8''${utf8Name}`;
349	  }
350	
351	  // Let browsers cache the redirect itself (matches the old 1h response
352	  // cache). The presigned URL lives 6h so a redirect cached for up to 1h can
353	  // never point at an expired signature, and long video sessions don't
354	  // outlive the URL. (Practical ceiling: the signature also dies with the
