/**
 * Bound a generation promise so it ALWAYS settles: the dedupe map entry is
 * only removed when the promise settles, so a hung generation (e.g. a stalled
 * S3 read — the image path has no inner timeout) would otherwise wedge every
 * future request for that file until a process restart.
 */
function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => {
      // The abandoned inner promise may still reject later — swallow it so it
      // can't surface as an unhandled rejection.
      promise.catch(() => {});
      reject(new MediaError('Thumbnail generation timed out.'));
    }, ms);
    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (err) => {
        clearTimeout(timer);
        reject(err);
      }
    );
  });
}

