/**
 * Accumulates scopes from the path by splitting it by '/' and
 * accumulating the segments to create a list of scopes.
 * For example, for the path
 * `/project/123/transaction/456/scope`, it will return:
 * [
 *   'project',
 *   'project/123',
 *   'project/123/transaction/456',
 *   'project/123/transaction/456/scope'
 * ]
 * @param path
 * @returns
 */
export const accumulateScopes = (
  path: string,
  result?: any | any[],
  method?: 'create' | 'update' | 'delete' | 'bulk'
): string[] => {
  const scopes: string[] = [];
  let paramAccumulator = '';
  path = trimStringByChars(path, ['/']);
  path.split('/').forEach((param, index) => {
    paramAccumulator += index === 0 ? param : '/' + param;
    scopes.push(paramAccumulator);
  });
  if (Array.isArray(result)) {
    result.forEach((item) => {
      scopes.push(paramAccumulator + '/' + (item.id as string));
    });
  } else {
    switch (method) {
      case 'create':
        scopes.push(paramAccumulator + '/' + (result.id as string));
        break;
    }
  }
  return scopes;
};

