export async function saveFile(key, file) {
  await file.mv(pathFor(key)); // express-fileupload moves the temp file
  metadata.set(key, { mimetype: file.mimetype, name: file.name });
}

/** Generate a width-400 JPEG thumbnail for image types — same as production. */
export async function saveThumbnail(key, file) {
  if (!file.mimetype?.startsWith('image/') || file.mimetype === 'image/svg+xml') {
    return null;
  }
  const thumbnailKey = `thumb:${key}`;
  try {
    await sharp(pathFor(key))
      .resize({ width: 400, withoutEnlargement: true })
      .jpeg({ quality: 85 })
      .toFile(pathFor(thumbnailKey));
    metadata.set(thumbnailKey, { mimetype: 'image/jpeg', name: `${key}.jpg` });
    return thumbnailKey;
  } catch {
    return null;
  }
}

export async function sendFile(key, response) {
  const filePath = pathFor(key);
  try {
    await fs.access(filePath);
  } catch {
    return response.status(404).json({ error: 'not found' });
  }
  const info = metadata.get(key);
  if (info?.mimetype) response.setHeader('Content-Type', info.mimetype);
  response.setHeader('Cache-Control', 'max-age=3600, must-revalidate');
  createReadStream(filePath).pipe(response);
}

export async function deleteFile(key) {
  await fs.rm(pathFor(key), { force: true });
  await fs.rm(pathFor(`thumb:${key}`), { force: true });
}

/**
 * storage-s3.mjs — the S3 storage driver, shaped like a production setup:
 * uploads stream to a private bucket, thumbnails are generated server-side
 * with sharp, and GET requests 302-redirect to short-lived presigned URLs
 * so S3 serves the bytes (including Range requests for video).
 *
 * Env: AWS credentials via the standard chain, plus
 *   S3_BUCKET=my-files-bucket  AWS_REGION=us-east-1  STORAGE=s3
 */
import { promises as fs } from 'node:fs';
import sharp from 'sharp';
import {
  S3Client,
  PutObjectCommand,
  GetObjectCommand,
  DeleteObjectCommand,
} from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

const BUCKET = process.env.S3_BUCKET;
const SIGNED_URL_TTL_SECONDS = 6 * 60 * 60;
const s3 = new S3Client({});

export async function saveFile(key, file) {
  await s3.send(
    new PutObjectCommand({
      Bucket: BUCKET,
      Key: key,
      Body: await fs.readFile(file.tempFilePath),
      ContentType: file.mimetype,
      Metadata: { originalname: encodeURIComponent(file.name) },
    }),
  );
}

/** Width-400 JPEG thumbnail, generated before the temp file is discarded. */
export async function saveThumbnail(key, file) {
  if (!file.mimetype?.startsWith('image/') || file.mimetype === 'image/svg+xml') {
    return null;
  }
  const thumbnailKey = `thumb:${key}`;
  try {
    const body = await sharp(file.tempFilePath)
      .resize({ width: 400, withoutEnlargement: true })
      .jpeg({ quality: 85 })
      .toBuffer();
    await s3.send(
      new PutObjectCommand({
        Bucket: BUCKET,
        Key: thumbnailKey,
        Body: body,
        ContentType: 'image/jpeg',
      }),
    );
    return thumbnailKey;
  } catch {
    return null;
  }
}

/** Auth here, bytes from S3: redirect to a presigned GET URL. */
export async function sendFile(key, response) {
  const url = await getSignedUrl(
    s3,
    new GetObjectCommand({ Bucket: BUCKET, Key: key }),
    { expiresIn: SIGNED_URL_TTL_SECONDS },
  );
  response.setHeader('Cache-Control', 'max-age=3600, must-revalidate');
  response.redirect(302, url);
}

export async function deleteFile(key) {
  await s3.send(new DeleteObjectCommand({ Bucket: BUCKET, Key: key }));
  await s3.send(new DeleteObjectCommand({ Bucket: BUCKET, Key: `thumb:${key}` }));
}

