  }
  get methodMs() {
    return ref<number | null>(null);
  }
  get boxRunning() {
    return ref(false);
  }

  async runCreation() {
    this.running.value = true;
    this.ivueMs.value = this.reactiveMs.value = this.composableMs.value = null;
    // let the button paint before blocking
    await this.nextTick();
    this.ivueMs.value = benchIvue();
    await this.nextTick();
    this.reactiveMs.value = benchReactive();
    await this.nextTick();
    this.composableMs.value = benchComposable();
    this.running.value = false;
  }

  async runInteractiveBox() {
    this.boxRunning.value = true;
    await this.nextTick();
    const { InteractiveBox } = await import('./model/InteractiveBox');

    // 1. creation — instances retained in an array, nothing elidable
    const instances = new Array(INSTANCE_COUNT);
    const creationStart = performance.now();
    for (let index = 0; index < INSTANCE_COUNT; index++) {
      instances[index] = new InteractiveBox.Class({ id: index });
    }
    this.boxCreationMs.value = performance.now() - creationStart;
    let alive = 0;
    for (let index = 0; index < INSTANCE_COUNT; index += 997) {
      if (instances[index]) alive++;
    }
    if (alive < 0) throw new Error('unreachable');

    // 2. method dispatch — one instance, a prototype-bound method, N calls
    const benchmarkInstance = instances[0];
    const methodStart = performance.now();
    for (let index = 0; index < CALL_COUNT; index++) {
      benchmarkInstance.calculatePhysics();
    }
    this.methodMs.value = performance.now() - methodStart;
    this.boxRunning.value = false;
  }

  nextTick() {
    return new Promise((resolve) => setTimeout(resolve, 30));
  }

  format(value: number | null) {
    return value === null ? '—' : `${value.toFixed(1)} ms`;
  }

  ratio(value: number | null) {
    return value === null || this.ivueMs.value === null || this.ivueMs.value === 0
      ? ''
      : `${(value / this.ivueMs.value).toFixed(1)}× slower`;
  }
}

export namespace BenchmarksExample {
  export const $Class = $BenchmarksExample; // raw — children `extends` this
  export const Class = Reactive($Class); // reactive — you `new` this
  export type Instance = typeof Class.Instance; // defineExpose type & reactive() interop
}

// FormulaGridExample.ts — the formula-grid route's state, in ivue. The
// MODEL (Sheet + FormulaCell) is the exact code the measured RESULTS.md
// numbers were produced with; this class is the page around it.
// `fast-formula-parser` loads via a dynamic import inside create(), so the
// route costs nothing until you build a sheet.
import { ref, shallowRef } from 'vue';
import { Reactive } from '../../ivue';
import {
  COLS,
  ROW_HEIGHT,
  VIEWPORT_HEIGHT,
  OVERSCAN,
  colLabel,
} from './formula-logic';
import type { Sheet as SheetModel } from './Sheet';
import { useRowWindow } from '../benchmarks/useRowWindow';

class $FormulaGridExample {
  // MUTABLE STATE — the sheet is replaced wholesale; shallowRef keeps a
  // million cells out of the deep-proxy machinery.
  get sheet() {
    return shallowRef<SheetModel | null>(null);
  }
  get loading() {
    return ref(false);
  }
  get creationMs() {
    return ref(0);
  }
  get editing() {
    return ref<{ r: number; c: number } | null>(null);
  }
  // re-trace deps after an edit (traceDeps is not reactive)
  get depsBump() {
    return ref(0);
  }

  // COMPOSABLE — the row window, hosted whole, created on first touch.
  private get $window() {
    return useRowWindow({
      rowCount: () => (this.sheet.value ? this.sheet.value.rows : 0),
      rowHeight: ROW_HEIGHT,
      viewportHeight: VIEWPORT_HEIGHT,
      overscan: OVERSCAN,
    });
  }
  get window() {
    return this.$window;
  }
  get scrollEl() {
    return this.$window.scrollEl;
  }

  // DERIVED — plain getters; zero allocations per instance.
  get hasModel() {
    return this.sheet.value !== null;
  }
  get modelCells() {
    return this.sheet.value ? this.sheet.value.rows * COLS : 0;
  }
  get mountedCells() {
    return this.$window.visibleRows.value.length * COLS;
  }
  get activeCell() {
    const active = this.editing.value;
    if (!active || !this.sheet.value) return null;
    return this.sheet.value.cellAt(active.r + 1, active.c + 1) ?? null;
  }
  get activeDeps(): string[] {
    void this.depsBump.value;
    const active = this.editing.value;
    const model = this.sheet.value;
    if (!active || !model) return [];
    return model
      .traceDeps(active.r + 1, active.c + 1)
      .map(([row, col]) => this.a1(row - 1, col - 1));
  }

  async create(rows: number) {
    this.loading.value = true;
    this.editing.value = null;
    // The parser ships in its own lazy chunk; first click pays it once.
    const { Sheet } = await import('./Sheet');
    const start = performance.now();
    const model = new Sheet(rows, COLS);
    this.creationMs.value = performance.now() - start;
    this.sheet.value = model;
    this.loading.value = false;
  }

  isEditing(row: number, col: number) {
    return (
      !!this.editing.value &&
      this.editing.value.r === row &&
      this.editing.value.c === col
    );
  }

  edit(row: number, col: number) {
    this.editing.value = { r: row, c: col };
  }

  commitEdit() {
    this.editing.value = null;
    this.depsBump.value++;
  }

  a1(row0: number, col0: number) {
    return colLabel(col0) + (row0 + 1);
  }
}

export namespace FormulaGridExample {
  export const $Class = $FormulaGridExample; // raw — children `extends` this
  export const Class = Reactive($Class); // reactive — you `new` this
  export type Instance = typeof Class.Instance; // defineExpose type & reactive() interop
}

