1	// ServerApi.ts — the one client-side gateway the field components call.
2	//
3	// The transport is pluggable: the playground ships with the in-browser
4	// MockServer transport (localStorage data + IndexedDB media), and the same
5	// components run unchanged against a real HTTP backend — see
6	// server-node/server.mjs for a reference Express implementation of this
7	// exact contract. Swap transports with ServerApi.use(httpTransport(baseUrl)).
8	//
9	// The wire contract (shared by mock and real servers):
10	//   list endpoints:  GET <path>?filters=<expr>&sort=<col:asc,..>&page=&rowsPerPage=
11	//                    → { data: Row[], pagination?: { page, rowsPerPage, rowsNumber } }
12	//   entity create:   POST <path> { ...fields } → { data: Row }
13	//   entity update:   PUT <path>/<id> { ...fields } → { data: Row }
14	//   media upload:    POST /media/upload (multipart) → { data: MediaRow[] }
15	//   media bytes:     GET /media/file/<key> → the file (or a redirect to it)
16	
17	export interface Pagination {
18	  page: number;
19	  rowsPerPage: number;
20	  rowsNumber: number;
21	}
22	
23	export interface ListResult<Row = any> {
24	  data: Row[];
25	  pagination?: Pagination;
26	}
27	
28	export interface MediaRow {
29	  id: string;
30	  key: string;
31	  name: string;
32	  mimetype: string;
33	  size: number;
34	  /** Resolvable URL for the bytes — `/media/file/<key>` on a real server. */
35	  url: string;
36	  /** Resolvable URL for a reduced-size preview when the type supports one. */
37	  thumbnailUrl: string;
38	  createdAt: string;
39	}
40	
41	export interface RequestOptions {
42	  query?: string;
43	  payload?: any;
44	  /** Multipart file payload for media uploads. */
45	  files?: File[];
46	}
47	
48	export interface ServerTransport {
49	  request(
50	    method: 'GET' | 'POST' | 'PUT' | 'DELETE',
51	    path: string,
52	    options?: RequestOptions,
53	  ): Promise<any>;
54	}
55	
56	let transport: ServerTransport | null = null;
57	
58	/** The response envelope is `{ data, pagination? }` — unwrap like an app would. */
59	const unwrap = (response: any) => response?.data ?? response;
60	
61	export const ServerApi = {
62	  /** Install a transport (the mock by default; an HTTP transport in real apps). */
63	  use(nextTransport: ServerTransport) {
64	    transport = nextTransport;
65	  },
66	
67	  get active(): ServerTransport {
68	    if (!transport) {
69	      throw new Error(
70	        'ServerApi has no transport — call ServerApi.use(...) first.',
71	      );
72	    }
73	    return transport;
74	  },
75	
76	  async getCustom(path: string): Promise<any> {
77	    return unwrap(await this.active.request('GET', path));
78	  },
79	
80	  /** List call that PRESERVES the pagination envelope. */
81	  async getPaginated<Row = any>(path: string): Promise<ListResult<Row>> {
82	    const response = await this.active.request('GET', path);
83	    return {
84	      data: response?.data ?? response ?? [],
85	      pagination: response?.pagination,
86	    };
87	  },
88	
89	  async postCustom(path: string, payload?: any): Promise<any> {
90	    return unwrap(await this.active.request('POST', path, { payload }));
91	  },
92	
93	  async putCustom(path: string, payload?: any): Promise<any> {
94	    return unwrap(await this.active.request('PUT', path, { payload }));
95	  },
96	
97	  async deleteCustom(path: string): Promise<any> {
98	    return unwrap(await this.active.request('DELETE', path));
99	  },
100	
101	  media: {
102	    async upload(files: File[], name?: string): Promise<MediaRow[]> {
103	      const response = await ServerApi.active.request(
104	        'POST',
105	        '/media/upload',
106	        { files, payload: { name } },
107	      );
108	      return response?.data ?? response ?? [];
109	    },
110	
111	    async get(ids: string[]): Promise<MediaRow[]> {
112	      const query = ids.map((id, index) => `ids[${index}]=${id}`).join('&');
113	      return (await ServerApi.getCustom(`/media?${query}`)) ?? [];
114	    },
115	
116	    async update(payload: {
117	      id: string;
118	      name?: string;
119	      caption?: string;
120	    }): Promise<MediaRow> {
121	      return await ServerApi.postCustom('/media/update', payload);
122	    },
123	
124	    async remove(id: string): Promise<void> {
125	      await ServerApi.deleteCustom(`/media/${id}`);
126	    },
127	  },
128	};
