async (page) => {
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e).slice(0,250)));
  await page.goto('http://localhost:4176/#/choose-field');
  await page.waitForTimeout(2500);
  const out = {};
  out.sections = await page.locator('.field-grid section h3').allInnerTexts();
  // 1. server-search contact: type in the Assignee field
  const assignee = page.locator('section', { hasText: 'search from the backend' }).locator('input').first();
  await assignee.click();
  await assignee.fill('grace');
  await page.waitForTimeout(1200);
  out.searchResults = await page.locator('.q-menu .q-item').allInnerTexts();
  // pick it
  await page.locator('.q-menu .q-item').first().click();
  await page.waitForTimeout(400);
  out.picked = (await page.locator('section', { hasText: 'search from the backend' }).innerText()).slice(0, 120).replace(/\n/g,' | ');
  out.errors = errors;
  return JSON.stringify(out, null, 1);
}

