  const errs = [];
  page.on('pageerror', (e) => errs.push((e.stack || String(e)).slice(0,300)));
  await page.goto('about:blank');
  await page.goto('http://localhost:4177/#/choose-field');
  await page.waitForTimeout(3500);
  const out = {};
  out.qfields = await page.locator('.q-field').count();
  out.sections = (await page.locator('.field-grid section h3').allInnerTexts()).length;
  // server search
  const assignee = page.locator('section', { hasText: 'search from the backend' }).locator('input').first();
  await assignee.click();
  await assignee.pressSequentially('grace', { delay: 40 });
  await page.waitForTimeout(1400);
  out.searchMenu = (await page.locator('.q-menu .q-item').allInnerTexts()).slice(0,3);
  if (out.searchMenu.length) {
    await page.locator('.q-menu .q-item').first().click();
    await page.waitForTimeout(400);
  }
  out.pickedValue = await page.locator('section', { hasText: 'search from the backend' }).locator('.q-field__native').innerText().catch(()=>'-');
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

