async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.stack || String(e)).slice(0,300)));
  await page.goto('about:blank');
  await page.goto('http://localhost:4177/#/media-field');
  await page.waitForTimeout(3500);
  const out = {};
  out.sections = await page.locator('.field-stack section h3').allInnerTexts();
  // upload a generated image into the gallery via the hidden input
  const galleryInput = page.locator('section', { hasText: 'Gallery' }).locator('input[type=file]').first();
  // create a small png buffer in-page
  const dataUrl = await page.evaluate(() => {
    const c = document.createElement('canvas'); c.width = 80; c.height = 60;
    const g = c.getContext('2d'); g.fillStyle = '#6366f1'; g.fillRect(0,0,80,60);
    g.fillStyle = '#34d399'; g.fillRect(10,10,40,30);
    return c.toDataURL('image/png');
  });
  const base64 = dataUrl.split(',')[1];
  await galleryInput.setInputFiles({ name: 'test-image.png', mimeType: 'image/png', buffer: Buffer.from(base64, 'base64') });
  await page.waitForTimeout(2500);
  out.galleryAfterUpload = (await page.locator('section', { hasText: 'Gallery' }).innerText()).slice(0,200).replace(/\n/g,' | ');
  out.thumbs = await page.locator('section', { hasText: 'Gallery' }).locator('img').count();
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.stack || String(e)).slice(0,300)));
  await page.goto('about:blank');
  await page.goto('http://localhost:4177/#/media-field');
  await page.waitForTimeout(3500);
  const out = {};
  out.sections = await page.locator('.field-stack section h3').allInnerTexts();
  // upload by driving the page's own input via DataTransfer inside the browser
  out.uploadDispatched = await page.evaluate(async () => {
    const section = [...document.querySelectorAll('.field-stack section')].find(s => s.textContent.includes('Gallery'));
    const input = section?.querySelector('input[type=file]');
    if (!input) return 'no input found';
    const canvas = document.createElement('canvas'); canvas.width = 80; canvas.height = 60;
    const g = canvas.getContext('2d'); g.fillStyle = '#6366f1'; g.fillRect(0,0,80,60);
    const blob = await new Promise(r => canvas.toBlob(r, 'image/png'));
    const file = new File([blob], 'test-image.png', { type: 'image/png' });
    const dt = new DataTransfer();
    dt.items.add(file);
    input.files = dt.files;
    input.dispatchEvent(new Event('change', { bubbles: true }));
    return 'dispatched';
  });
  await page.waitForTimeout(3000);
  const gallery = page.locator('.field-stack section', { hasText: 'Gallery' });
  out.thumbs = await gallery.locator('img').count();
  out.galleryText = (await gallery.innerText()).slice(0,180).replace(/\n/g,' | ');
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

