async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  const P = 'http://localhost:4178/#/';

  // --- playground: every route renders + a key interaction each ---
  await page.goto('about:blank');
  await page.goto(P + 'counter'); await page.waitForTimeout(500);
  await page.getByRole('button', { name: '+1', exact: true }).click();
  out.counter = (await page.locator('.vals').innerText()).includes('2') || (await page.locator('.vals').innerText()).includes('1');

  await page.goto(P + 'derived'); await page.waitForTimeout(400);
  await page.locator('input.slider').fill('33'); await page.waitForTimeout(250);
  out.derived = (await page.locator('.vals').innerText()).includes('91');

  await page.goto(P + 'lifecycle'); await page.waitForTimeout(400);
  await page.getByRole('button', { name: 'start', exact: true }).click();
  await page.locator('input.slider').fill('39'); await page.waitForTimeout(250);
  out.lifecycle = (await page.locator('.vals').innerText()).includes('ON');

  await page.goto(P + 'inheritance'); await page.waitForTimeout(400);
  await page.getByRole('button', { name: 'price +$6' }).click();
  out.inheritance = (await page.locator('.receipt').innerText()).includes('54');

  await page.goto(P + 'pointer'); await page.waitForTimeout(400);
  await page.mouse.move(400, 300); await page.waitForTimeout(300);
  out.pointer = (await page.locator('.vals').innerText()).length > 5;

  await page.goto(P + 'virtual-scroller'); await page.waitForTimeout(800);
  await page.getByRole('button', { name: 'jump to #500,000' }).click();
  await page.waitForTimeout(1200);
  out.virtualScroller = (await page.locator('.stage-body').innerText()).includes('500,000');

  return JSON.stringify({ ...out, errors: errs }, null, 1);
}

