// quasar-docs-loader.ts — the docs app installs Quasar lazily, only when a
// page embeds a field example. Pages without field demos never download a
// byte of Quasar; the plugin, its CSS and the icon font ride in the field
// embeds' lazy chunks.
import type { App } from 'vue';

let app: App | null = null;
let installing: Promise<void> | null = null;

export function registerDocsApp(instance: App) {
  app = instance;
}

export function installQuasar(): Promise<void> {
  installing ??= (async () => {
    if (!app) throw new Error('quasar-docs-loader: no app registered');
    const [{ Quasar }] = await Promise.all([
      import('quasar'),
      // @ts-expect-error — css side-effect imports have no types
      import('quasar/dist/quasar.css'),
      // @ts-expect-error — css side-effect imports have no types
      import('@quasar/extras/material-icons/material-icons.css'),
    ]);
    app.use(Quasar, { config: { dark: true } }); // embeds render on a dark pane
  })();
  return installing;
}

// ExampleFieldEmbed.ts — the shared state for docs embeds of the Quasar
// field examples: installs Quasar into the docs app, then resolves the
// playground route component. Everything loads lazily, on mount.
import { markRaw, ref, type Component } from 'vue';
import { Reactive } from '../../../../../lib/Reactive';
import { installQuasar } from '../../quasar-docs-loader';

class $ExampleFieldEmbed {
  #load: () => Promise<{ default: Component }>;

  constructor(load: () => Promise<{ default: Component }>) {
    this.#load = load;
    this.mountExample();
  }

  get example() {
    return ref<Component | null>(null);
  }
  get failure() {
    return ref('');
  }

  async mountExample() {
    try {
      await installQuasar();
      const module = await this.#load();
      this.example.value = markRaw(module.default);
    } catch (error) {
      this.failure.value = String(error);
    }
  }
}

export namespace ExampleFieldEmbed {
  export const $Class = $ExampleFieldEmbed; // raw — children `extends` this
  export const Class = Reactive($Class); // reactive — you `new` this
  export type Instance = typeof Class.Instance; // defineExpose type & reactive() interop
}

/* Docs embed frame for the playground field examples: the examples style
   themselves for a dark pane, so the frame provides one in both themes. */
.field-embed {
  margin: 20px 0;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 14px;
  background: #0d1226;
  overflow: hidden;
}
.field-embed__loading,
.field-embed__error {
  margin: 0;
  padding: 28px 20px;
  font-size: 13px;
  color: #8b95b5;
}
.field-embed__error {
  color: #f87171;
}
/* the example panes bring their own padding; neutralize page-width caps */
.field-embed .pane {
  max-width: none;
}
</style>

