async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  const P = 'http://localhost:4178/#/';

  // media-field on the production build: upload
  await page.goto('about:blank');
  await page.goto(P + 'media-field'); await page.waitForTimeout(3500);
  await page.evaluate(async () => {
    const section = [...document.querySelectorAll('.field-stack section')].find(s => s.textContent.includes('Gallery'));
    const input = section?.querySelector('input[type=file]');
    const canvas = document.createElement('canvas'); canvas.width = 120; canvas.height = 90;
    const g = canvas.getContext('2d'); g.fillStyle = '#34d399'; g.fillRect(0,0,120,90);
    const blob = await new Promise(r => canvas.toBlob(r, 'image/png'));
    const file = new File([blob], 'e2e.png', { type: 'image/png' });
    const dt = new DataTransfer(); dt.items.add(file);
    input.files = dt.files;
    input.dispatchEvent(new Event('change', { bubbles: true }));
  });
  await page.waitForTimeout(2500);
  out.mediaThumbs = await page.locator('.field-stack section', { hasText: 'Gallery' }).locator('img').count();

  // create-tag flow on choose-field
  await page.goto(P + 'choose-field'); await page.waitForTimeout(3000);
  const tagSection = page.locator('.field-grid section', { hasText: 'Create new options' });
  const tagInput = tagSection.locator('input').first();
  await tagInput.click();
  await tagInput.pressSequentially('zzz-new', { delay: 30 });
  await page.waitForTimeout(1300);
  const createItem = page.locator('.q-menu .q-item').filter({ hasText: /zzz-new|Create/ }).first();
  out.createItemText = await createItem.innerText().catch(() => 'none');
  await createItem.click();
  await page.waitForTimeout(1200);
  out.createdChip = (await tagSection.innerText()).includes('zzz-new');

  // formula grid quick check on this build
  await page.goto(P + 'formula-grid'); await page.waitForTimeout(500);
  await page.getByRole('button', { name: 'Create 100k cells' }).click();
  await page.waitForTimeout(6000);
  out.formula = (await page.locator('.mono').first().innerText()).includes('100,000');

  // benchmarks quick check
  await page.goto(P + 'benchmarks'); await page.waitForTimeout(500);
  await page.getByRole('button', { name: /Create 100,000 instances/ }).click();
  await page.waitForTimeout(3000);
  out.bench = (await page.locator('.vals').first().innerText()).includes('ms');

  // flyweight loads
  await page.goto(P + 'flyweight-grid'); await page.waitForTimeout(1500);
  out.flyweight = (await page.locator('.stage-body').innerText()).includes('20,000,000');

  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
