  await page.locator('.q-menu .q-item').first().click(); await page.waitForTimeout(300);

  const variantSection = page.locator('.field-grid section', { hasText: 'people / companies' });
  await variantSection.locator('input').first().click(); await page.waitForTimeout(1200);
  await page.locator('.ivue-choose__variants .q-btn', { hasText: 'Companies' }).click();
  await page.waitForTimeout(1200);
  out.variants = (await page.locator('.q-menu .q-item').allInnerTexts()).some(t => t.includes('Bell Labs'));
  await page.keyboard.press('Escape'); await page.waitForTimeout(300);

  const tagSection = page.locator('.field-grid section', { hasText: 'Create new options' });
  const tagInput = tagSection.locator('input').first();
  await tagInput.click();
  await tagInput.pressSequentially('e2e-tag', { delay: 30 });
  await page.waitForTimeout(1500);
  const menuText = await page.locator('.q-menu').innerText().catch(()=> 'NO MENU');
  out.createMenu = menuText.replace(/\n/g,' | ').slice(0,120);
  const createItem = page.locator('.q-menu .q-item[clickable], .q-menu .q-item--clickable').first();
  if (await createItem.count()) {
    await createItem.click(); await page.waitForTimeout(1200);
    out.created = (await tagSection.innerText()).includes('e2e-tag');
  }

  // media-field: upload + square tile check
  await page.goto(P + 'media-field'); await page.waitForTimeout(3000);
  await page.evaluate(async () => {
    const section = [...document.querySelectorAll('.field-stack section')].find(s => s.textContent.includes('Gallery'));
    const input = section?.querySelector('input[type=file]');
    const canvas = document.createElement('canvas'); canvas.width = 120; canvas.height = 90;
    const g = canvas.getContext('2d'); g.fillStyle = '#6366f1'; g.fillRect(0,0,120,90);
    const blob = await new Promise(r => canvas.toBlob(r, 'image/png'));
    const file = new File([blob], 'square-check.png', { type: 'image/png' });
    const dt = new DataTransfer(); dt.items.add(file);
    input.files = dt.files;
    input.dispatchEvent(new Event('change', { bubbles: true }));
  });
  await page.waitForTimeout(2500);
  const tile = page.locator('.field-stack section', { hasText: 'Gallery' }).locator('img').first();
  out.mediaUploaded = await tile.count() > 0;
  if (out.mediaUploaded) {
    const box = await tile.boundingBox();
    out.tileSquare = box ? Math.abs(box.width - box.height) < 2 : false;
  }
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

