async (page) => {
  // still light mode on choose page — find what paints the dark band behind the h1
  const info = await page.evaluate(() => {
    const h1 = document.querySelector('h1');
    let el = h1;
    const chain = [];
    while (el && chain.length < 8) {
      const bg = getComputedStyle(el).backgroundColor;
      if (bg !== 'rgba(0, 0, 0, 0)') chain.push({ cls: el.className?.toString().slice(0,60), bg });
      el = el.parentElement;
    }
    return { chain, htmlDark: document.documentElement.classList.contains('dark') };
  });
  return JSON.stringify(info, null, 1);
}

