async (page) => {
  const result = await page.evaluate(async () => {
    const makeFile = async (name) => {
      const canvas = document.createElement('canvas');
      canvas.width = 320; canvas.height = 200;
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = '#3a7'; ctx.fillRect(0,0,320,200);
      const blob = await new Promise(r => canvas.toBlob(r, 'image/png'));
      return new File([blob], name, { type: 'image/png' });
    };
    const fields = Array.from(document.querySelectorAll('.media-field'));
    const info = fields.map(f => ({
      extended: !!f.closest('.extended-media') || f.classList.contains('extended-media'),
      label: f.querySelector('.media-field__label')?.textContent?.trim(),
    }));
    // upload into first base field and into extended field
    const baseField = fields.find(f => !f.classList.contains('extended-media'));
    const extField = fields.find(f => f.classList.contains('extended-media'));
    const upload = async (field, name) => {
      const input = field.querySelector('input[type=file]');
      const dt = new DataTransfer();
      dt.items.add(await makeFile(name));
      input.files = dt.files;
      input.dispatchEvent(new Event('change', { bubbles: true }));
    };
    await upload(baseField, 'base-test.png');
    if (extField) await upload(extField, 'ext-test.png');
    return info;
  });
  await page.waitForTimeout(1500);
  const measure = await page.evaluate(() => {
    const fields = Array.from(document.querySelectorAll('.media-field'));
    const baseField = fields.find(f => !f.classList.contains('extended-media'));
    const extField = fields.find(f => f.classList.contains('extended-media'));
    const rect = el => el ? { w: Math.round(el.getBoundingClientRect().width), h: Math.round(el.getBoundingClientRect().height) } : null;
    const baseItem = baseField?.querySelector('.media-field__item');
    const baseThumb = baseField?.querySelector('.media-field__thumb');
    const extTile = extField?.querySelector('.extended-media__thumb');
    return {
      baseItemCount: baseField?.querySelectorAll('.media-field__item').length,
      baseItem: rect(baseItem),
      baseThumb: rect(baseThumb),
      extItemCount: extField?.querySelectorAll('.extended-media__tile').length,
      extThumb: rect(extTile),
      extFound: !!extField,
    };
  });
  return { fieldsFound: result, measure };
}

