  const out = {};
  await page.goto('about:blank');
  await page.goto('http://localhost:4182/#/media-field');
  await page.waitForTimeout(4000);
  // preexisting section starts full: 3 seeded rows
  const pre = page.locator('.field-grid section', { hasText: 'Preexisting' });
  out.preexistingImgs = await pre.locator('img').count();
  out.preexistingNames = (await pre.innerText()).match(/aurora|ember|tide/g)?.length ?? 0;
  // base row geometry: thumbnail ~120x60
  const thumb = pre.locator('img').first();
  const tb = await thumb.boundingBox();
  out.rowThumbShape = tb ? `${Math.round(tb.width)}x${Math.round(tb.height)}` : 'none';
  // extended: upload then check square tile
  await page.evaluate(async () => {
    const section = [...document.querySelectorAll('.field-grid section')].find(s => s.textContent.includes('Extended'));
    const input = section?.querySelector('input[type=file]');
    const canvas = document.createElement('canvas'); canvas.width = 100; canvas.height = 70;
    const g = canvas.getContext('2d'); g.fillStyle = '#f59e0b'; g.fillRect(0,0,100,70);
    const blob = await new Promise(r => canvas.toBlob(r, 'image/png'));
    const file = new File([blob], 'ext.png', { type: 'image/png' });
    const dt = new DataTransfer(); dt.items.add(file);
    input.files = dt.files;
    input.dispatchEvent(new Event('change', { bubbles: true }));
  });
  await page.waitForTimeout(2500);
  const extTile = page.locator('.field-grid section', { hasText: 'Extended' }).locator('img').first();
  const eb = await extTile.boundingBox();
  out.extendedTile = eb ? `${Math.round(eb.width)}x${Math.round(eb.height)} square=${Math.abs(eb.width-eb.height)<2}` : 'none';
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
})(page);
