async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  await page.goto('about:blank');
  await page.setViewportSize({ width: 1360, height: 900 });
  // home light: lockup + visible mark
  await page.goto('http://localhost:4180/ivue/');
  await page.waitForTimeout(1200);
  const isDark = await page.evaluate(() => document.documentElement.classList.contains('dark'));
  if (isDark) { await page.locator('.VPSwitchAppearance').first().click(); await page.waitForTimeout(800); }
  out.lightLockupVisible = await page.locator('.ivh-lockup--light').isVisible();
  out.darkLockupHidden = !(await page.locator('.ivh-lockup--dark').isVisible());
  await page.screenshot({ path: 'tmp/home-light.png', clip: { x: 0, y: 0, width: 1360, height: 760 } });
  // toggle dark
  await page.locator('.VPSwitchAppearance').first().click();
  await page.waitForTimeout(900);
  out.darkLockupVisible = await page.locator('.ivh-lockup--dark').isVisible();
  await page.screenshot({ path: 'tmp/home-dark.png', clip: { x: 0, y: 0, width: 1360, height: 760 } });
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

