async (page) => {
  // find the stylesheet rule that makes body bg dark in light mode
  await page.goto('http://localhost:4180/ivue/');
  await page.waitForTimeout(800);
  const isDark = await page.evaluate(() => document.documentElement.classList.contains('dark'));
  if (isDark) { await page.locator('.VPSwitchAppearance').first().click(); await page.waitForTimeout(800); }
  return await page.evaluate(() => {
    const val = getComputedStyle(document.documentElement).getPropertyValue('--vp-c-bg').trim();
    // find matching rules that set --vp-c-bg
    const hits = [];
    for (const sheet of document.styleSheets) {
      let rules; try { rules = sheet.cssRules; } catch { continue; }
      for (const rule of rules) {
        if (rule.style && rule.style.getPropertyValue('--vp-c-bg')) {
          hits.push(rule.selectorText + ' → ' + rule.style.getPropertyValue('--vp-c-bg'));
        }
      }
    }
    return JSON.stringify({ effective: val, htmlDark: document.documentElement.className, hits: hits.slice(0, 10) }, null, 1);
  });
}

