async (page) => {
  return await page.evaluate(() => {
    const hits = [];
    for (const sheet of document.styleSheets) {
      let rules; try { rules = sheet.cssRules; } catch { continue; }
      for (const rule of rules) {
        if (rule.selectorText && rule.style?.backgroundColor && /(^|,| )body\b/.test(rule.selectorText)) {
          hits.push(rule.selectorText + ' → ' + rule.style.backgroundColor + ' [' + (sheet.href ?? 'inline').split('/').pop() + ']');
        }
        // also check nested layer rules
        if (rule.cssRules) {
          for (const inner of rule.cssRules) {
            if (inner.selectorText && inner.style?.backgroundColor && /(^|,| )body\b/.test(inner.selectorText)) {
              hits.push('[layer] ' + inner.selectorText + ' → ' + inner.style.backgroundColor);
            }
          }
        }
      }
    }
    return JSON.stringify(hits.slice(0, 12), null, 1);
  });
}

