async (page) => {
  return await page.evaluate(() => {
    for (const sheet of document.styleSheets) {
      let rules; try { rules = sheet.cssRules; } catch { continue; }
      for (let i = 0; i < rules.length; i++) {
        const rule = rules[i];
        if (rule.selectorText === 'body' && rule.style?.backgroundColor === 'rgb(11, 16, 32)') {
          // grab neighboring rules for context
          const around = [];
          for (let j = Math.max(0, i - 3); j < Math.min(rules.length, i + 3); j++) {
            around.push(rules[j].cssText?.slice(0, 110));
          }
          return JSON.stringify({ index: i, cssText: rule.cssText, around }, null, 1);
        }
      }
    }
    return 'not found';
  });
}

