async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  await page.goto('about:blank');
  await page.goto('http://localhost:4184/#/choose-field');
  await page.waitForTimeout(3000);

  // 1. per-option icons in "Icons & descriptions": open menu, check q-icon per item
  const iconSection = page.locator('.field-grid section', { hasText: 'Icons & descriptions' });
  await iconSection.locator('.q-field__control').first().click();
  await page.waitForTimeout(700);
  out.optionIcons = await page.locator('.q-menu .q-item .q-icon').count();
  out.iconNames = await page.evaluate(() => [...document.querySelectorAll('.q-menu .q-item .q-icon')].map(i => i.textContent).slice(0,4));
  await page.keyboard.press('Escape'); await page.waitForTimeout(300);

  // 2. duplicate tag guard: create 'dup-tag' twice
  const tagSection = page.locator('.field-grid section', { hasText: 'Create new options' });
  const tagInput = tagSection.locator('input').first();
  for (let round = 0; round < 2; round++) {
    await tagInput.click();
    await tagInput.pressSequentially('dup-tag', { delay: 25 });
    await page.waitForTimeout(1300);
    const createItem = page.locator('.q-menu .q-item--clickable').first();
    if (await createItem.count()) { await createItem.click(); await page.waitForTimeout(1000); }
    else { await page.keyboard.press('Escape'); }
    await page.waitForTimeout(400);
  }
  out.dupChipCount = (await tagSection.innerText()).split('dup-tag').length - 1;

  // 3. avatar spacing: measure gap between avatar and name in contact option
  const contactSection = page.locator('.field-grid section', { hasText: 'search from the backend' });
  await contactSection.locator('input').first().click();
  await page.waitForTimeout(1300);
  out.avatarGap = await page.evaluate(() => {
    const item = document.querySelector('.q-menu .contact-field__option');
    const avatar = item?.querySelector('.q-item__section--avatar');
    const label = item?.querySelector('.q-item__section:not(.q-item__section--avatar)');
    if (!avatar || !label) return 'missing';
    return Math.round(label.getBoundingClientRect().left - avatar.getBoundingClientRect().right) + 'px';
  });
  await page.keyboard.press('Escape');
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

