async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  await page.goto('about:blank');
  await page.goto('http://localhost:4185/#/choose-field');
  await page.waitForTimeout(3000);

  // per-option icons: open the Icons & descriptions menu (click the arrow)
  const iconSection = page.locator('.field-grid section', { hasText: 'Icons & descriptions' });
  await iconSection.locator('.q-select').click();
  await page.waitForTimeout(900);
  out.menuOpen = await page.locator('.q-menu').count();
  out.optionIcons = await page.locator('.q-menu .q-item .q-item__section--avatar .q-icon').count();
  out.iconGlyphs = await page.evaluate(() => [...document.querySelectorAll('.q-menu .q-item .q-icon')].map(i => i.textContent).slice(0,5));
  // pick Pro to test chip-less selection
  if (out.menuOpen) { await page.locator('.q-menu .q-item').nth(1).click(); await page.waitForTimeout(400); }

  // variants: open menu, measure variant button font-size + padding
  const variantSection = page.locator('.field-grid section', { hasText: 'people / companies' });
  await variantSection.locator('input').first().click();
  await page.waitForTimeout(1300);
  out.variantBtnStyle = await page.evaluate(() => {
    const btn = document.querySelector('.ivue-choose__variant-btn');
    if (!btn) return 'missing';
    const cs = getComputedStyle(btn);
    return `font=${cs.fontSize} pad=${cs.padding}`;
  });
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);

  // team chips: select two contacts to render avatar chips, then screenshot both chip styles
  const team = page.locator('.field-grid section', { hasText: 'avatar chips' });
  const teamInput = team.locator('input').first();
  await teamInput.click(); await page.waitForTimeout(1300);
  await page.locator('.q-menu .q-item').first().click(); await page.waitForTimeout(600);
  await page.locator('.q-menu .q-item').nth(1).click(); await page.waitForTimeout(600);
  await page.keyboard.press('Escape'); await page.waitForTimeout(300);

  // tags: create one to render a base chip
  const tagSection = page.locator('.field-grid section', { hasText: 'Create new options' });
  const tagInput = tagSection.locator('input').first();
  await tagInput.click();
  await tagInput.pressSequentially('paddington', { delay: 25 });
  await page.waitForTimeout(1300);
  const createItem = page.locator('.q-menu .q-item--clickable').first();
  if (await createItem.count()) { await createItem.click(); await page.waitForTimeout(900); }
  await page.keyboard.press('Escape');
  await page.waitForTimeout(400);
  await page.screenshot({ path: 'tmp/choose-polish.png', fullPage: false, clip: { x: 250, y: 0, width: 1030, height: 900 } });
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

