await (async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  await page.goto('about:blank');
  await page.goto('http://localhost:4190/#/choose-field');
  await page.waitForTimeout(3000);

  // 1. Icons & descriptions: PLANS with per-item icons now (engine fix)
  const iconSection = page.locator('.field-grid section', { hasText: 'Icons & descriptions' });
  await iconSection.locator('.q-select').click();
  await page.waitForTimeout(900);
  out.iconItems = await page.evaluate(() => [...document.querySelectorAll('.q-menu .q-item')].map(i => ({
    text: i.querySelector('.q-item__label')?.textContent,
    icon: i.querySelector('.q-icon')?.textContent,
    gap: (() => { const a = i.querySelector('.q-item__section--avatar'); const m = i.querySelector('.q-item__section--main'); return a && m ? Math.round(m.getBoundingClientRect().left - a.querySelector('.q-icon').getBoundingClientRect().right) : null; })(),
  })).slice(0, 4));
  // select Hobby to test singular chip-less selection
  await page.locator('.q-menu .q-item').first().click();
  await page.waitForTimeout(400);
  await page.screenshot({ path: 'tmp/final-icons.png', clip: { x: 250, y: 60, width: 1030, height: 500 } });
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
})(page);
