async (page) => {
  const out = {};
  // chips: tags (base) + team (avatar) + variants chips + basic singular
  const tagSection = page.locator('.field-grid section', { hasText: 'Create new options' });
  const tagInput = tagSection.locator('input').first();
  await tagInput.click();
  await tagInput.pressSequentially('urgent', { delay: 25 });
  await page.waitForTimeout(1300);
  const urgentItem = page.locator('.q-menu .q-item', { hasText: 'urgent' }).first();
  if (await urgentItem.count()) { await urgentItem.click(); }
  await page.keyboard.press('Escape'); await page.waitForTimeout(400);
  out.tagChipPad = await page.evaluate(() => {
    const chip = [...document.querySelectorAll('.q-chip')].find(c => c.textContent.includes('urgent'));
    return chip ? getComputedStyle(chip).padding : 'no chip';
  });

  const team = page.locator('.field-grid section', { hasText: 'avatar chips' });
  await team.locator('input').first().click(); await page.waitForTimeout(1300);
  await page.locator('.q-menu .q-item').first().click(); await page.waitForTimeout(500);
  await page.keyboard.press('Escape'); await page.waitForTimeout(300);
  out.contactChipPad = await page.evaluate(() => {
    const chip = document.querySelector('.contact-field__chip');
    return chip ? getComputedStyle(chip).padding : 'no chip';
  });

  await page.screenshot({ path: 'tmp/final-choose.png', fullPage: true });

  // media: seeds + preview dialog contrast
  await page.goto('http://localhost:4190/#/media-field');
  await page.waitForTimeout(4500);
  const pre = page.locator('.field-grid section', { hasText: 'Preexisting' });
  out.seedImgs = await pre.locator('img').count();
  // open preview of first seed
  await pre.locator('img').first().click();
  await page.waitForTimeout(900);
  out.previewOpen = await page.locator('.media-preview').count();
  out.nameColor = await page.evaluate(() => {
    const name = document.querySelector('.media-preview__name');
    const footer = document.querySelector('.media-preview__footer');
    return name && footer ? getComputedStyle(name).color + ' on ' + getComputedStyle(footer).backgroundColor : 'missing';
  });
  await page.screenshot({ path: 'tmp/final-preview.png', clip: { x: 150, y: 50, width: 1100, height: 750 } });
  return JSON.stringify(out, null, 1);
}

