import pathlib
# style the create-affordance term as a circular-bordered chip-like token, single quotes gone
p = pathlib.Path('examples/playground/src/examples/fields/choose-field/ChooseField.ts'); s = p.read_text()
s = s.replace("""    const text = `${this.createLabel || 'Create new'} "${this.searchTerm.value.trim()}"`;
    this.displayedOptions.value = [
      {
        // label under BOTH the default key and the active optionLabel key,
        // so custom option-label props still render the affordance text
        label: text,
        ...(this.props.optionLabel ? { [this.props.optionLabel]: text } : {}),
        icon: 'add',
        value: CREATE_OPTION_VALUE,
      },""", """    const term = this.searchTerm.value.trim();
    const text = `${this.createLabel || 'Create new'} '${term}'`;
    this.displayedOptions.value = [
      {
        // label under BOTH the default key and the active optionLabel key,
        // so custom option-label props still render the affordance text
        label: text,
        ...(this.props.optionLabel ? { [this.props.optionLabel]: text } : {}),
        createTerm: term,
        icon: 'add',
        value: CREATE_OPTION_VALUE,
      },""")
p.write_text(s)

# render the term as a circular-bordered token in the option row
p = pathlib.Path('examples/playground/src/examples/fields/choose-field/ChooseField.vue'); s = p.read_text()
s = s.replace("""            <q-item-section>
              <q-item-label>{{ choose.optionLabelOf(scope.opt) }}</q-item-label>
              <q-item-label v-if="choose.optionDescriptionOf(scope.opt)" caption>
                {{ choose.optionDescriptionOf(scope.opt) }}
              </q-item-label>
            </q-item-section>""", """            <q-item-section>
              <q-item-label v-if="scope.opt?.createTerm">
                {{ choose.createLabel || 'Create new' }}
                <span class="ivue-choose__create-term">{{
                  scope.opt.createTerm
                }}</span>
              </q-item-label>
              <q-item-label v-else>
                {{ choose.optionLabelOf(scope.opt) }}
              </q-item-label>
              <q-item-label v-if="choose.optionDescriptionOf(scope.opt)" caption>
                {{ choose.optionDescriptionOf(scope.opt) }}
              </q-item-label>
            </q-item-section>""")
s = s.replace("""/* Quasar reserves 56px for icon sections — a comfortable 10px gap instead */""", """/* the to-be-created value renders as a round chip-like token */
.ivue-choose__create-term {
  display: inline-block;
  padding: 1px 12px;
  margin-left: 4px;
  border: 1px solid currentColor;
  border-radius: 50px;
  font-weight: 500;
}

/* Quasar reserves 56px for icon sections — a comfortable 10px gap instead */""")
p.write_text(s)
print('create token styled')
EOF
