async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  await page.goto('about:blank');
  await page.goto('http://localhost:4194/#/choose-field');
  await page.waitForTimeout(3000);
  // create-term token + chip colors
  const tagSection = page.locator('.field-grid section', { hasText: 'Create new options' });
  const tagInput = tagSection.locator('input').first();
  await tagInput.click();
  await tagInput.pressSequentially('rounded-check', { delay: 25 });
  await page.waitForTimeout(1300);
  out.token = await page.evaluate(() => {
    const term = document.querySelector('.ivue-choose__create-term');
    if (!term) return 'missing';
    const cs = getComputedStyle(term);
    return `text='${term.textContent}' radius=${cs.borderRadius} border=${cs.borderTopWidth}`;
  });
  await page.screenshot({ path: 'tmp/create-token.png', clip: { x: 250, y: 350, width: 1030, height: 420 } });
  await page.locator('.q-menu .q-item').first().click();
  await page.waitForTimeout(900);
  out.tagChipColor = await page.evaluate(() => {
    const chip = [...document.querySelectorAll('.q-chip')].find(c => c.textContent.includes('rounded-check'));
    return chip ? getComputedStyle(chip).color : 'no chip';
  });
  // team avatar chip color
  const team = page.locator('.field-grid section', { hasText: 'avatar chips' });
  await team.locator('input').first().click(); await page.waitForTimeout(1300);
  await page.locator('.q-menu .q-item').first().click(); await page.waitForTimeout(500);
  await page.keyboard.press('Escape'); await page.waitForTimeout(300);
  out.contactChipColor = await page.evaluate(() => {
    const chip = document.querySelector('.contact-field__chip');
    return chip ? getComputedStyle(chip).color : 'no chip';
  });
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

