async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,150)));
  const out = {};
  await page.goto('about:blank');
  await page.goto('http://localhost:4199/#/media-field');
  await page.waitForTimeout(4000);
  const pre = page.locator('.field-grid section', { hasText: 'Preexisting' });
  // 3 seeds → sort buttons visible on hover; capture order, move first down
  out.namesBefore = await page.evaluate(() => {
    const section = [...document.querySelectorAll('.field-grid section')].find(s => s.textContent.includes('Preexisting'));
    return [...section.querySelectorAll('.media-field__item input')].map(i => i.value).filter(Boolean).slice(0,3);
  });
  const firstRow = pre.locator('.media-field__item').first();
  await firstRow.hover();
  await page.waitForTimeout(300);
  out.sortVisible = await firstRow.locator('.media-field__sort .q-btn').count();
  await firstRow.locator('.media-field__sort .q-btn').nth(1).click(); // move down
  await page.waitForTimeout(500);
  out.namesAfter = await page.evaluate(() => {
    const section = [...document.querySelectorAll('.field-grid section')].find(s => s.textContent.includes('Preexisting'));
    return [...section.querySelectorAll('.media-field__item input')].map(i => i.value).filter(Boolean).slice(0,3);
  });
  // single-image section: no sort controls (1 max)
  out.singleHasSort = await page.locator('.field-grid section', { hasText: 'Single image' }).locator('.media-field__sort').count();
  // solid borders check
  out.dropBorder = await page.evaluate(() => {
    const drop = document.querySelector('.media-field__drop, [class*=drop]');
    return drop ? getComputedStyle(drop).borderStyle : 'n/a';
  });
  out.addLabelFont = await page.evaluate(() => {
    const label = document.querySelector('.media-field__add-label');
    return label ? getComputedStyle(label).fontSize : 'n/a';
  });
  // preview rename: open preview of first seed, rename
  await pre.locator('img').first().click();
  await page.waitForTimeout(900);
  await page.locator('.media-preview__name').click();
  await page.waitForTimeout(400);
  const input = page.locator('.media-preview__name-input');
  out.renameInput = await input.count();
  if (out.renameInput) {
    await input.fill('renamed-from-preview');
    await page.keyboard.press('Enter');
    await page.waitForTimeout(900);
    out.renamedShown = (await page.locator('.media-preview__name').innerText()).includes('renamed-from-preview');
  }
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

