    await page.locator('.VPSwitchAppearance').first().click();
    await page.waitForTimeout(800);
  }
  out.lockup = await page.locator('.ivh-lockup--light').isVisible();
  const cell = page.locator('.ix-moat .cell').first();
  await cell.hover(); await page.waitForTimeout(300);
  out.moatHoverBg = await cell.evaluate((el) => getComputedStyle(el).backgroundColor);
  await page.screenshot({ path: 'tmp/final-home-light.png', clip: { x: 0, y: 0, width: 1360, height: 700 } });
  // guide page demo in light: DemoBox themed
  await page.goto('http://localhost:4180/ivue/guide/getting-started.html');
  await page.waitForTimeout(1000);
  out.demoBoxBgLight = await page.locator('.dbx').first().evaluate((el) => getComputedStyle(el).backgroundColor);
  // flyweight page in light: body not dark anymore
  await page.goto('http://localhost:4180/ivue/guide/introduction.html');
  await page.waitForTimeout(700);
  out.bodyBgLight = await page.evaluate(() => getComputedStyle(document.body).backgroundColor);
  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 1);
}

