    const probe = document.createElement('span');
    probe.style.cssText = 'display:inline-block;width:1px;height:1px;vertical-align:baseline;';
    sub.appendChild(probe);
    const baselineY = probe.getBoundingClientRect().bottom;
    probe.remove();
    const markBottom = document.querySelector('.mark').getBoundingClientRect().bottom;
    const subRect = sub.getBoundingClientRect();
    const nameRect = document.querySelector('.name').getBoundingClientRect();
    return JSON.stringify({ baselineY, markBottom, subTop: subRect.top, nameBottom: nameRect.bottom, overlap: subRect.top < nameRect.bottom });
  });
})(page);
```

