async (page) => {
  const out = {};
  await page.setViewportSize({ width: 375, height: 720 });
  for (const slug of ['choose-field', 'media-field']) {
    await page.goto('about:blank');
    await page.goto('http://localhost:4201/#/' + slug);
    await page.waitForTimeout(3500);
    out[slug] = await page.evaluate(() => {
      const doc = document.documentElement;
      const overflow = doc.scrollWidth - doc.clientWidth;
      // find widest offenders
      const wide = [...document.querySelectorAll('*')]
        .filter(el => el.getBoundingClientRect().right > doc.clientWidth + 2)
        .slice(0, 5)
        .map(el => `${el.className?.toString?.().split(' ')[0] || el.tagName} w=${Math.round(el.getBoundingClientRect().width)}`);
      const grid = document.querySelector('.field-grid');
      const gridCols = grid ? getComputedStyle(grid).gridTemplateColumns : 'none';
      return { overflow, wide, gridCols: gridCols.split(' ').length + ' cols: ' + gridCols.slice(0, 60) };
    });
  }
  await page.screenshot({ path: 'tmp/mobile-choose.png' });
  return JSON.stringify(out, null, 1);
}

