  await page.setViewportSize({ width: 320, height: 800 });
  await page.goto('about:blank');
  await page.goto('http://localhost:4208/#/choose-field');
  await page.waitForTimeout(3200);
  const out = {};
  // longest contact: Margaret Hamilton (MIT Instrumentation Lab) in avatar-chips multiple
  const team = page.locator('.field-grid section', { hasText: 'avatar chips' });
  await team.locator('input').first().click();
  await page.waitForTimeout(1400);
  await page.locator('.q-menu .q-item', { hasText: 'Margaret Hamilton' }).first().click();
  await page.waitForTimeout(400);
  await page.locator('.q-menu .q-item', { hasText: 'Katherine Johnson' }).first().click();
  await page.waitForTimeout(400);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(400);
  out.overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
  out.chips = await page.evaluate(() => [...document.querySelectorAll('.contact-field__chip')].map(c => {
    const field = c.closest('.q-field__control');
    return `chip=${Math.round(c.getBoundingClientRect().width)} field=${Math.round(field.getBoundingClientRect().width)} inside=${c.getBoundingClientRect().right <= field.getBoundingClientRect().right + 1}`;
  }));
  // single select with long email in server-search field
  const assignee = page.locator('.field-grid section', { hasText: 'search from the backend' });
  await assignee.locator('input').first().click();
  await page.waitForTimeout(1300);
  await page.locator('.q-menu .q-item', { hasText: 'Margaret' }).first().click();
  await page.waitForTimeout(500);
  out.overflowAfterSingle = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
  const chipBox = await page.locator('.contact-field__chip').first().boundingBox();
  await page.screenshot({ path: 'tmp/chip-ellipsis.png', clip: { x: 0, y: Math.max(0, chipBox.y - 160), width: 320, height: 380 } });
  await page.setViewportSize({ width: 1280, height: 800 });
  return JSON.stringify(out, null, 1);
}

