async (page) => {
  await page.goto('http://localhost:4180/ivue/');
  await page.waitForTimeout(1200);
  const style = await page.locator('.ivh-title .shine').evaluate((el) => {
    const cs = getComputedStyle(el);
    return { duration: cs.animationDuration, image: cs.backgroundImage.slice(0, 90) };
  });
  // capture two frames a second apart to see the streak move
  const el = page.locator('.ivh-title');
  await el.screenshot({ path: 'tmp/shine-f1.png' });
  await page.waitForTimeout(1000);
  await el.screenshot({ path: 'tmp/shine-f2.png' });
  return JSON.stringify(style);
}

